import 'dart:convert';
import 'dart:typed_data';

import 'package:flutter/widgets.dart';

/// Canonical AIMS Flow graphic already used on the approved login screen.
class AimsFlowLogo extends StatelessWidget {
  const AimsFlowLogo({
    super.key,
    this.width = 48,
    this.height = 48,
  });

  final double width;
  final double height;

  static final Uint8List _bytes = base64Decode('');

  @override
  Widget build(BuildContext context) => Image.memory(
        _bytes,
        width: width,
        height: height,
        fit: BoxFit.contain,
        filterQuality: FilterQuality.high,
        gaplessPlayback: true,
      );
}
